/// Computes the greatest common divisor of two positive integers using
/// the subtraction-based Euclidean algorithm.
///
/// Preconditions: m > 0, n > 0.
pub fn gcd_i(m: u64, n: u64) -> u64 {
    assert!(m > 0 && n > 0, "inputs must be strictly positive");

    let mut a = m;
    let mut b = n;

    while a != b {
        if a > b {
            // a - b is safe and stays positive because a > b >= 1
            a -= b;
        } else {
            // b - a is safe and stays positive because b > a >= 1
            b -= a;
        }
    }

    a
}

